func:
const kelasId = msg.req.query.kelas_id;
const mataPelajaranId = msg.req.query.mata_pelajaran_id;
const tanggalMulai = msg.req.query.tanggal_mulai;
const tanggalSelesai = msg.req.query.tanggal_selesai;

if (!kelasId) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        message: "Parameter kelas_id wajib diisi."
    };
    return msg;
}

const params = [Number(kelasId)];
let parameterIndex = 2;

let filterMapel = "";
let filterTanggal = "";

if (mataPelajaranId) {
    filterMapel = `
        AND guru_mapel.mata_pelajaran_id = $${parameterIndex}
    `;

    params.push(Number(mataPelajaranId));
    parameterIndex++;
}

if (tanggalMulai) {
    filterTanggal += `
        AND sesi.tanggal >= $${parameterIndex}::date
    `;

    params.push(tanggalMulai);
    parameterIndex++;
}

if (tanggalSelesai) {
    filterTanggal += `
        AND sesi.tanggal <= $${parameterIndex}::date
    `;

    params.push(tanggalSelesai);
    parameterIndex++;
}

msg.query = `
    SELECT
        siswa.id AS siswa_id,
        siswa.nisn,
        siswa.nis,
        siswa.nama_lengkap,
        siswa.jenis_kelamin,

        COUNT(presensi.id)
            FILTER (WHERE presensi.status = 'hadir')
            AS jumlah_hadir,

        COUNT(presensi.id)
            FILTER (WHERE presensi.status = 'sakit')
            AS jumlah_sakit,

        COUNT(presensi.id)
            FILTER (WHERE presensi.status = 'izin')
            AS jumlah_izin,

        COUNT(presensi.id)
            FILTER (WHERE presensi.status = 'tanpa_keterangan')
            AS jumlah_tanpa_keterangan,

        COUNT(presensi.id)
            AS jumlah_presensi

    FROM siswa

    LEFT JOIN kelas
        ON siswa.kelas_id = kelas.id

    LEFT JOIN presensi
        ON presensi.siswa_id = siswa.id

    LEFT JOIN sesi
        ON presensi.sesi_id = sesi.id

    LEFT JOIN guru_mapel
        ON sesi.guru_mapel_id = guru_mapel.id

    WHERE siswa.kelas_id = $1
      AND siswa.status = 'aktif'
      ${filterMapel}
      ${filterTanggal}

    GROUP BY
        siswa.id,
        siswa.nisn,
        siswa.nis,
        siswa.nama_lengkap,
        siswa.jenis_kelamin

    ORDER BY
        siswa.nama_lengkap;
`;

msg.params = params;

return msg;

const hasil = msg.payload;

msg.headers = {
    "Content-Type": "application/json; charset=utf-8"
};

msg.payload = {
    success: true,
    data: hasil
};

return msg;
